/* ==UserStyle==
@name         Google Keep – Vazirmatn Global
@namespace    keep-vazirmatn
@version      1.0.1
@match        https://keep.google.com/*
==/UserStyle== */

/* Load Vazirmatn from Google Fonts */
@font-face {
  font-family: 'Vazirmatn';
  src: local('Vazirmatn'),
       url('https://fonts.gstatic.com/s/vazirmatn/v13/Dxx78j6PP2D_kU2muijPEKnp1_s.woff2') format('woff2');
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

html {
  font-size: 95% !important;
}

body, div, span, textarea, input, [contenteditable="true"] {
  font-family: "Vazirmatn", sans-serif !important;
}

/* Note title styling */
div[aria-label="Title"],
div[contenteditable="true"][role="textbox"]:first-of-type {
  font-weight: 700 !important;   /* Bold */
}

/* Grid card titles */
div[role="heading"] {
  font-weight: 700 !important;
}

/* Grid (home page) note titles – exact match */
div[role="textbox"][aria-multiline="true"][contenteditable="false"] {
  font-size: 98% !important;
	font-weight: 700 !important;
}
